-- Migration 636: a booking whose cancellation request was rejected or withdrawn can get a new request.
--
-- CrmCancellation.BookingId was UNIQUE (one request row per booking, closed ones included), so once a request was
-- rejected or withdrawn the booking could never be cancelled through a new request. Business decision 2026-11-12:
-- one LIVE request per booking; rejected and withdrawn requests stay as history (constants/crmStatuses.js
-- CANCELLATION_DROPPED_STATUSES: Rejected, Withdrawn, and Cancelled on older rows). Same pattern as 572-574.
-- The old constraint's name was generated by SQL Server (differs per database), so it is looked up. Safe to run again.
DECLARE @uq SYSNAME, @sql NVARCHAR(400);
SELECT TOP 1 @uq = kc.name
  FROM sys.key_constraints kc
  JOIN sys.index_columns ic ON ic.object_id = kc.parent_object_id AND ic.index_id = kc.unique_index_id
  JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
 WHERE kc.parent_object_id = OBJECT_ID(N'dbo.CrmCancellation') AND kc.type = 'UQ' AND c.name = N'BookingId'
   AND (SELECT COUNT(*) FROM sys.index_columns x WHERE x.object_id = kc.parent_object_id AND x.index_id = kc.unique_index_id) = 1;
IF @uq IS NOT NULL
BEGIN
  SET @sql = N'ALTER TABLE dbo.CrmCancellation DROP CONSTRAINT ' + QUOTENAME(@uq);
  EXEC sp_executesql @sql;
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.CrmCancellation') AND name = N'UX_CrmCancellation_Booking_Live')
  CREATE UNIQUE INDEX UX_CrmCancellation_Booking_Live ON dbo.CrmCancellation (BookingId)
    WHERE Status <> N'Rejected' AND Status <> N'Withdrawn' AND Status <> N'Cancelled';
GO
